// Makes the six base workbooks of the static order page (site/base/<project>-<material>.xlsx): one section with
// one item each, generated by the bot's own excel.mjs, so the page starts from exactly what the bot produces.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {parseOrder} from './parser.mjs';
import {generate} from './excel.mjs';
const root = path.dirname(fileURLToPath(import.meta.url));
await fs.mkdir(path.join(root, 'site', 'base'), {recursive: true});
for (const project of ['C3D1', 'C3D2']) for (const material of ['HDG', 'SS316', 'EPDM']) {
  const order = parseOrder(`${project} ${material === 'EPDM' ? 'Gasket' : material}\nRequester Name: R\nTitle: T\n${material === 'EPDM' ? 'DN100 PN10' : 'M16 nut'} = 1`);
  const file = await generate(order, `base-${project}-${material}`);
  await fs.copyFile(file, path.join(root, 'site', 'base', `${project}-${material}.xlsx`));
  console.log(`base ${project} ${material}`);
}
